import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { ArrowLeft, Download, RefreshCw, Mail, Phone, Building2, Globe } from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import * as XLSX from 'xlsx';

interface BatchDetails {
  id: string;
  name: string;
  description: string | null;
  status: string;
  total_jobs: number;
  completed_jobs: number;
  failed_jobs: number;
  delay_seconds: number;
  created_at: string;
  started_at: string | null;
  completed_at: string | null;
}

interface Job {
  id: string;
  query: string;
  location: string | null;
  pages: number;
  status: string;
  result_count: number;
  executed_at: string | null;
  search_id: string | null;
  actual_contact_count?: number; // Conteggio reale dal database
}

interface Contact {
  id: string;
  name: string | null;
  organization: string | null;
  email: string | null;
  phone: string | null;
  website: string | null;
  created_at: string;
}

export default function BatchDetails() {
  const { batchId } = useParams();
  const navigate = useNavigate();
  const { toast } = useToast();
  
  const [batch, setBatch] = useState<BatchDetails | null>(null);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!batchId) return;
    
    loadBatchData();
    
    // Auto-refresh SOLO se il batch è in elaborazione
    // Se è completato, disabilita il refresh per risparmiare query
    if (batch?.status === 'running') {
      const interval = setInterval(loadBatchData, 30000);
      return () => clearInterval(interval);
    }
  }, [batchId, batch?.status]);

  const loadBatchData = async () => {
    try {
      // Load batch info
      const { data: batchData, error: batchError } = await supabase
        .from('search_batches')
        .select('*')
        .eq('id', batchId)
        .single();

      if (batchError) throw batchError;
      setBatch(batchData);

      // Load jobs
      const { data: jobsData, error: jobsError } = await supabase
        .from('search_jobs')
        .select('*')
        .eq('batch_id', batchId)
        .order('created_at', { ascending: true });

      if (jobsError) throw jobsError;

      // Load all contacts from completed jobs
      const completedSearchIds = (jobsData || [])
        .filter(j => j.search_id)
        .map(j => j.search_id);

      if (completedSearchIds.length > 0) {
        const { data: contactsData, error: contactsError } = await supabase
          .from('contacts')
          .select('*')
          .in('search_id', completedSearchIds)
          .order('created_at', { ascending: false });

        if (contactsError) throw contactsError;
        setContacts(contactsData || []);

        // Conta i contatti reali per ogni job
        const contactCountsBySearchId = (contactsData || []).reduce((acc, contact) => {
          if (contact.search_id) {
            acc[contact.search_id] = (acc[contact.search_id] || 0) + 1;
          }
          return acc;
        }, {} as Record<string, number>);

        // Aggiorna i job con il conteggio reale
        const jobsWithCounts = (jobsData || []).map(job => ({
          ...job,
          actual_contact_count: job.search_id ? (contactCountsBySearchId[job.search_id] || 0) : 0
        }));
        setJobs(jobsWithCounts);
      } else {
        setJobs(jobsData || []);
      }

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const exportContacts = () => {
    if (contacts.length === 0) {
      toast({
        title: "Nessun contatto",
        description: "Non ci sono contatti da esportare",
        variant: "destructive",
      });
      return;
    }

    const worksheet = XLSX.utils.json_to_sheet(
      contacts.map(c => ({
        Nome: c.name || '',
        Organizzazione: c.organization || '',
        Email: c.email || '',
        Telefono: c.phone || '',
        Sito: c.website || '',
      }))
    );

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Contatti');
    XLSX.writeFile(workbook, `${batch?.name || 'batch'}_contatti.xlsx`);

    toast({
      title: "✓ Export completato",
      description: `${contacts.length} contatti esportati`,
    });
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
      pending: "secondary",
      running: "default",
      completed: "outline",
      failed: "destructive",
    };
    return <Badge variant={variants[status] || "default"}>{status.toUpperCase()}</Badge>;
  };

  const getProgress = () => {
    if (!batch || batch.total_jobs === 0) return 0;
    return Math.round((batch.completed_jobs / batch.total_jobs) * 100);
  };

  if (loading || !batch) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <RefreshCw className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-background to-secondary/20 p-8">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center gap-4">
          <Button variant="ghost" onClick={() => navigate('/batch')}>
            <ArrowLeft className="mr-2 h-4 w-4" />
            Torna ai Batch
          </Button>
          <div className="flex-1">
            <h1 className="text-4xl font-bold">{batch.name}</h1>
            {batch.description && (
              <p className="text-muted-foreground mt-1">{batch.description}</p>
            )}
          </div>
          {getStatusBadge(batch.status)}
        </div>

        {/* Stats Card */}
        <Card className="border-2 border-primary/30">
          <CardHeader>
            <CardTitle>Progresso Batch</CardTitle>
            <CardDescription>
              {batch.completed_jobs} / {batch.total_jobs} ricerche completate
              {batch.failed_jobs > 0 && ` • ${batch.failed_jobs} fallite`}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <Progress value={getProgress()} className="h-3" />
            
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="p-4 bg-primary/10 rounded-lg">
                <div className="text-3xl font-bold text-primary">{contacts.length}</div>
                <div className="text-sm text-muted-foreground">Contatti Trovati</div>
              </div>
              <div className="p-4 bg-secondary/10 rounded-lg">
                <div className="text-3xl font-bold text-secondary">{batch.completed_jobs}</div>
                <div className="text-sm text-muted-foreground">Completate</div>
              </div>
              <div className="p-4 bg-muted rounded-lg">
                <div className="text-3xl font-bold">{batch.total_jobs - batch.completed_jobs - batch.failed_jobs}</div>
                <div className="text-sm text-muted-foreground">In Coda</div>
              </div>
              <div className="p-4 bg-destructive/10 rounded-lg">
                <div className="text-3xl font-bold text-destructive">{batch.failed_jobs}</div>
                <div className="text-sm text-muted-foreground">Fallite</div>
              </div>
            </div>

            <Button onClick={exportContacts} className="w-full" disabled={contacts.length === 0}>
              <Download className="mr-2 h-4 w-4" />
              Esporta {contacts.length} Contatti in Excel
            </Button>
          </CardContent>
        </Card>

        {/* Jobs Status */}
        <Card>
          <CardHeader>
            <CardTitle>Ricerche del Batch</CardTitle>
            <CardDescription>Stato di ogni ricerca nel batch</CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Query</TableHead>
                  <TableHead>Località</TableHead>
                  <TableHead>Pagine</TableHead>
                  <TableHead>Stato</TableHead>
                  <TableHead className="text-right">Contatti</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {jobs.map((job) => (
                  <TableRow key={job.id}>
                    <TableCell className="font-mono text-xs max-w-md truncate">
                      {job.query}
                    </TableCell>
                    <TableCell>{job.location || '-'}</TableCell>
                    <TableCell>{job.pages}</TableCell>
                    <TableCell>{getStatusBadge(job.status)}</TableCell>
                    <TableCell className="text-right font-semibold">
                      {job.actual_contact_count ?? 0}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        {/* Contacts Table */}
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle>Contatti Trovati ({contacts.length})</CardTitle>
                <CardDescription>Tutti i contatti estratti da questo batch</CardDescription>
              </div>
              <Button variant="outline" onClick={loadBatchData}>
                <RefreshCw className="h-4 w-4" />
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            {contacts.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">
                <Mail className="h-12 w-12 mx-auto mb-4 opacity-50" />
                <p>Nessun contatto trovato ancora...</p>
                {batch.status === 'running' && (
                  <p className="text-sm mt-2">Le ricerche sono in corso, controlla tra qualche minuto</p>
                )}
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Nome</TableHead>
                    <TableHead>Organizzazione</TableHead>
                    <TableHead>Email</TableHead>
                    <TableHead>Telefono</TableHead>
                    <TableHead>Sito</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {contacts.map((contact) => (
                    <TableRow key={contact.id}>
                      <TableCell className="font-medium">{contact.name || '-'}</TableCell>
                      <TableCell>
                        {contact.organization && (
                          <div className="flex items-center gap-2">
                            <Building2 className="h-4 w-4 text-muted-foreground" />
                            {contact.organization}
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        {contact.email && (
                          <a href={`mailto:${contact.email}`} className="flex items-center gap-2 text-primary hover:underline">
                            <Mail className="h-4 w-4" />
                            {contact.email}
                          </a>
                        )}
                      </TableCell>
                      <TableCell>
                        {contact.phone && (
                          <div className="flex items-center gap-2">
                            <Phone className="h-4 w-4 text-muted-foreground" />
                            {contact.phone}
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        {contact.website && (
                          <a href={contact.website} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 text-primary hover:underline">
                            <Globe className="h-4 w-4" />
                            {contact.website}
                          </a>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { ArrowLeft, Upload, Play, Pause, Trash2, Download, Plus, FileDown, Eye } from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";

interface Batch {
  id: string;
  name: string;
  description: string | null;
  status: string;
  total_jobs: number;
  completed_jobs: number;
  failed_jobs: number;
  delay_seconds: number;
  created_at: string;
  started_at: string | null;
  completed_at: string | null;
}

interface Job {
  query: string;
  location: string | null;
  pages: number;
  target_names: string[] | null;
  country: string;
}

export default function BatchManager() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);
  
  // Form state
  const [batchName, setBatchName] = useState("");
  const [batchDescription, setBatchDescription] = useState("");
  const [delaySeconds, setDelaySeconds] = useState(120);
  const [csvContent, setCsvContent] = useState("");

  useEffect(() => {
    loadBatches();
    
    // NO auto-refresh! Ricaricare solo manualmente per ridurre le query
    // Se serve vedere gli aggiornamenti in tempo reale, l'utente usa il bottone Ricarica
  }, []);

  const loadBatches = async () => {
    try {
      const { data, error } = await supabase
        .from('search_batches')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setBatches(data || []);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const isExcel = file.name.endsWith('.xlsx') || file.name.endsWith('.xls');

    if (isExcel) {
      // Import XLSX dynamically
      const XLSX = await import('xlsx');
      const reader = new FileReader();
      reader.onload = (event) => {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const csvText = XLSX.utils.sheet_to_csv(firstSheet);
        setCsvContent(csvText);
      };
      reader.readAsArrayBuffer(file);
    } else {
      // CSV file
      const reader = new FileReader();
      reader.onload = (event) => {
        const text = event.target?.result as string;
        setCsvContent(text);
      };
      reader.readAsText(file);
    }
  };

  const createBatch = async () => {
    if (!batchName.trim()) {
      toast({
        title: "Errore",
        description: "Inserisci il nome del batch",
        variant: "destructive",
      });
      return;
    }

    try {
      let jobs: Job[] = [];
      
      // Parsing CSV solo se presente - supporta virgolette per campi con virgole
      if (csvContent.trim()) {
        const normalized = csvContent.replace(/\uFEFF/g, '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
        const linesArr = normalized.split('\n').filter(l => l.trim());
        const header = linesArr[0] || '';
        const sample = linesArr[1] || header;

        const detectDelimiter = (s: string) => {
          const candidates = [',', ';', '\t'];
          const counts = candidates.map(d => (s.match(new RegExp(`\\${d}`, 'g')) || []).length);
          const max = Math.max(...counts);
          return max > 0 ? candidates[counts.indexOf(max)] : ',';
        };

        const delimiter = detectDelimiter(sample);

        const parseLine = (line: string, delim: string) => {
          const out: string[] = [];
          let cur = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const ch = line[i];
            if (ch === '"') {
              if (inQuotes && line[i + 1] === '"') { cur += '"'; i++; }
              else { inQuotes = !inQuotes; }
            } else if (ch === delim && !inQuotes) {
              out.push(cur.trim());
              cur = '';
            } else {
              cur += ch;
            }
          }
          out.push(cur.trim());
          return out.map((t) => t.startsWith('"') && t.endsWith('"') ? t.slice(1, -1).replace(/""/g, '"') : t);
        };

        // Costruisci i job gestendo anche il caso in cui il country sia su una riga separata
        const rows: Job[] = [];
        for (const line of linesArr.slice(1)) {
          const parts = parseLine(line, delimiter).map(p => p.trim());

          // Linee che contengono solo il country (es. "it" o ",it"): assegnale alla riga precedente
          if (parts.length === 1 && parts[0]) {
            const maybeCountry = parts[0].replace(/^,/, '').toLowerCase();
            if (/^[a-z]{2}$/.test(maybeCountry) && rows.length > 0) {
              rows[rows.length - 1].country = maybeCountry;
              continue;
            }
          }

          let query = parts[0] || '';
          let location = parts[1] ? parts[1] : null;
          const pagesParsed = Number.parseInt(parts[2] || '');
          const targetNamesStr = parts[3] || '';
          const country = (parts[4] || '').trim();

          // Se la location è vuota ma la query contiene un separatore (tab/;) con città alla fine, recuperala
          if (!location && /\t|;/.test(query)) {
            const split = query.split(/\t|;/);
            if (split.length > 1) {
              query = split[0].trim();
              const possibleLoc = split.slice(1).join(' ').trim();
              if (possibleLoc) location = possibleLoc;
            }
          }

          // Se la riga è solo una country (es. ",it") non creare un job
          if (/^,?([a-z]{2})$/i.test(query) && !parts[1] && !parts[2] && !parts[3]) {
            const code = query.replace(/^,/, '').toLowerCase();
            if (rows.length > 0) rows[rows.length - 1].country = code;
            continue;
          }

          const job: Job = {
            query,
            location: location && location.length > 0 ? location : null,
            pages: Number.isFinite(pagesParsed) ? pagesParsed : 10,
            target_names: targetNamesStr ? targetNamesStr.split('|').map(n => n.trim()).filter(Boolean) : null,
            country: country || 'it',
          };

          rows.push(job);
        }

        jobs = rows.filter(j => j.query && j.query.length > 0);
      }

      // Get current user
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('User not authenticated');

      // Crea il batch
      const { data: batch, error: batchError } = await supabase
        .from('search_batches')
        .insert({
          name: batchName,
          description: batchDescription,
          total_jobs: jobs.length,
          delay_seconds: delaySeconds,
          user_id: user.id,
        })
        .select()
        .single();

      if (batchError) throw batchError;

      // Crea i job solo se ce ne sono
      if (jobs.length > 0) {
        const jobsToInsert = jobs.map(job => ({
          batch_id: batch.id,
          user_id: user.id,
          ...job,
        }));

        const { error: jobsError } = await supabase
          .from('search_jobs')
          .insert(jobsToInsert);

        if (jobsError) throw jobsError;
      }

      toast({
        title: "Successo",
        description: jobs.length > 0 
          ? `Batch "${batchName}" creato con ${jobs.length} ricerche`
          : `Batch "${batchName}" creato (vuoto)`,
      });

      // Reset form
      setBatchName("");
      setBatchDescription("");
      setCsvContent("");
      setShowCreateForm(false);
      loadBatches();

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage,
        variant: "destructive",
      });
    }
  };

  const startBatch = async (batchId: string) => {
    try {
      await supabase
        .from('search_batches')
        .update({ 
          status: 'running',
          started_at: new Date().toISOString()
        })
        .eq('id', batchId);

      toast({
        title: "Batch avviato",
        description: "Il processamento automatico è iniziato",
      });

      loadBatches();

      // Trigger immediate processing
      await supabase.functions.invoke('process-search-queue');

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage,
        variant: "destructive",
      });
    }
  };

  const pauseBatch = async (batchId: string) => {
    try {
      await supabase
        .from('search_batches')
        .update({ status: 'paused' })
        .eq('id', batchId);

      toast({
        title: "Batch in pausa",
        description: "Il processamento è stato messo in pausa",
      });

      loadBatches();
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage,
        variant: "destructive",
      });
    }
  };

  const deleteBatch = async (batchId: string) => {
    if (!confirm("Sei sicuro di voler eliminare questo batch?")) return;

    try {
      await supabase
        .from('search_batches')
        .delete()
        .eq('id', batchId);

      toast({
        title: "Batch eliminato",
      });

      loadBatches();
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage,
        variant: "destructive",
      });
    }
  };

  const downloadTemplate = async (format: 'csv' | 'xlsx' = 'xlsx') => {
    const data = [
      ['query', 'location', 'pages', 'target_names'],
      ['marketing agentur (site:linkedin.com) ("@gmail.com")', 'Berlin', '10', ''],
      ['werbeagentur (site:facebook.com) ("@gmail.com")', 'München', '10', 'maria|sara|laura'],
      ['digital marketing', 'Hamburg', '10', ''],
    ];

    if (format === 'xlsx') {
      const XLSX = await import('xlsx');
      const worksheet = XLSX.utils.aoa_to_sheet(data);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, 'Batch');
      XLSX.writeFile(workbook, 'batch_template.xlsx');
    } else {
      const template = `query,location,pages,target_names
"marketing agentur (site:linkedin.com) (""@gmail.com"")",Berlin,10,""
"werbeagentur (site:facebook.com) (""@gmail.com"")",München,10,"maria|sara|laura"
"digital marketing",Hamburg,10,""`;
      
      const blob = new Blob([template], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'batch_template.csv';
      a.click();
      URL.revokeObjectURL(url);
    }
  };

  const exportBatchJobs = async (batchId: string, batchName: string) => {
    try {
      const { data: jobs, error } = await supabase
        .from('search_jobs')
        .select('query, location, pages')
        .eq('batch_id', batchId)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!jobs || jobs.length === 0) {
        toast({
          title: "Nessun job",
          description: "Questo batch non contiene ricerche da esportare",
          variant: "destructive",
        });
        return;
      }

      // Crea CSV con virgolette per proteggere le virgole
      const csvHeader = 'query,location,pages\n';
      const csvRows = jobs.map(job => {
        const query = `"${(job.query || '').replace(/"/g, '""')}"`;
        const location = job.location || '';
        const pages = job.pages || 10;
        return `${query},${location},${pages}`;
      }).join('\n');

      const csvContent = csvHeader + csvRows;
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${batchName.replace(/[^a-z0-9]/gi, '_')}_batch.csv`;
      a.click();
      URL.revokeObjectURL(url);

      toast({
        title: "✓ Export completato",
        description: `${jobs.length} ricerche esportate`,
      });
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage,
        variant: "destructive",
      });
    }
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
      pending: "secondary",
      running: "default",
      completed: "outline",
      paused: "secondary",
      failed: "destructive",
    };
    return <Badge variant={variants[status] || "default"}>{status.toUpperCase()}</Badge>;
  };

  const getProgress = (batch: Batch) => {
    if (batch.total_jobs === 0) return 0;
    return Math.round((batch.completed_jobs / batch.total_jobs) * 100);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <p className="text-muted-foreground">Caricamento...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-background to-secondary/20 p-8">
      <div className="max-w-7xl mx-auto space-y-8">
        <div className="flex items-center gap-4">
          <Button variant="ghost" onClick={() => navigate('/dashboard')}>
            <ArrowLeft className="mr-2 h-4 w-4" />
            Dashboard
          </Button>
          <div className="flex-1">
            <h1 className="text-4xl font-bold">Gestione Code Automatiche</h1>
            <p className="text-muted-foreground mt-2">
              Crea e gestisci batch di ricerche automatizzate
            </p>
          </div>
          <Button onClick={() => setShowCreateForm(!showCreateForm)}>
            <Plus className="mr-2 h-4 w-4" />
            Nuovo Batch
          </Button>
        </div>

        {showCreateForm && (
          <Card className="border-2 border-primary/30">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <span className="text-primary">→</span> Crea Nuovo Batch
              </CardTitle>
              <CardDescription>
                Inserisci un nome per il batch. Puoi caricare un CSV con le ricerche o aggiungerle dopo.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Step 1: Nome e Configurazione */}
              <div className="space-y-4 p-4 rounded-lg bg-primary/5 border border-primary/20">
                <h3 className="font-semibold text-primary flex items-center gap-2">
                  1️⃣ Configurazione Base
                </h3>
                <div className="grid gap-4 md:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="batchName" className="text-foreground">
                      Nome Batch <span className="text-destructive">*</span>
                    </Label>
                    <Input
                      id="batchName"
                      placeholder="Es: Agenzie Marketing Germania"
                      value={batchName}
                      onChange={(e) => setBatchName(e.target.value)}
                      className={!batchName.trim() ? "border-destructive/50" : "border-primary/50"}
                      disabled={false}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="delay" className="text-foreground">Delay tra ricerche (secondi)</Label>
                    <Input
                      id="delay"
                      type="number"
                      value={delaySeconds}
                      onChange={(e) => setDelaySeconds(parseInt(e.target.value) || 120)}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="description" className="text-foreground">Descrizione (opzionale)</Label>
                  <Textarea
                    id="description"
                    placeholder="Descrivi l'obiettivo di questo batch..."
                    value={batchDescription}
                    onChange={(e) => setBatchDescription(e.target.value)}
                  />
                </div>
              </div>

              {/* Step 2: CSV Upload */}
              <div className="space-y-4 p-4 rounded-lg bg-secondary/5 border border-secondary/20">
                <div className="flex items-center justify-between">
                  <h3 className="font-semibold text-secondary flex items-center gap-2">
                    2️⃣ Carica File Excel/CSV <span className="text-muted-foreground text-sm">(opzionale)</span>
                  </h3>
                  <div className="flex gap-2">
                    <Button variant="outline" size="sm" onClick={() => downloadTemplate('xlsx')}>
                      <Download className="mr-2 h-4 w-4" />
                      Template Excel
                    </Button>
                    <Button variant="outline" size="sm" onClick={() => downloadTemplate('csv')}>
                      <Download className="mr-2 h-4 w-4" />
                      Template CSV
                    </Button>
                  </div>
                </div>
                
                <div className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
                  csvContent ? 'border-secondary bg-secondary/10' : 'border-border'
                }`}>
                  <Upload className={`mx-auto h-12 w-12 mb-4 ${csvContent ? 'text-secondary' : 'text-muted-foreground'}`} />
                  <Label htmlFor="csvFile" className="cursor-pointer">
                    <span className="text-primary hover:underline font-medium">
                      {csvContent ? '✓ File Caricato - Clicca per sostituire' : 'Clicca per caricare CSV'}
                    </span>
                    <Input
                      id="csvFile"
                      type="file"
                      accept=".csv,.xlsx,.xls"
                      className="hidden"
                      onChange={handleFileUpload}
                    />
                  </Label>
                  {csvContent && (
                    <div className="mt-3 text-sm space-y-1">
                      <p className="text-secondary font-semibold">
                        ✓ {csvContent.split('\n').length - 1} ricerche caricate
                      </p>
                      <p className="text-muted-foreground text-xs">
                        Formato: query, location, pages
                      </p>
                    </div>
                  )}
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-2 pt-4 border-t">
                <Button 
                  onClick={createBatch} 
                  className="flex-1 bg-primary hover:bg-primary/90"
                  disabled={!batchName.trim()}
                >
                  {!batchName.trim() ? 
                    '⚠️ Inserisci il nome del batch' : 
                    csvContent.trim() ? '✓ Crea Batch con CSV' : '✓ Crea Batch Vuoto'
                  }
                </Button>
                <Button variant="outline" onClick={() => {
                  setShowCreateForm(false);
                  setBatchName("");
                  setBatchDescription("");
                  setCsvContent("");
                }}>
                  Annulla
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        <Card>
          <CardHeader>
            <CardTitle>Batch Attivi</CardTitle>
          </CardHeader>
          <CardContent>
            {batches.length === 0 ? (
              <p className="text-center text-muted-foreground py-8">
                Nessun batch creato. Crea il tuo primo batch per iniziare!
              </p>
            ) : (
              <div className="space-y-4">
                {batches.map((batch) => (
                  <Card key={batch.id}>
                    <CardHeader>
                      <div className="flex items-start justify-between">
                        <div>
                          <CardTitle className="text-lg">{batch.name}</CardTitle>
                          {batch.description && (
                            <CardDescription>{batch.description}</CardDescription>
                          )}
                        </div>
                        {getStatusBadge(batch.status)}
                      </div>
                    </CardHeader>
                    <CardContent className="space-y-4">
                      <div className="space-y-2">
                        <div className="flex justify-between text-sm">
                          <span>Progresso</span>
                          <span className="font-medium">
                            {batch.completed_jobs} / {batch.total_jobs} completati
                            {batch.failed_jobs > 0 && ` (${batch.failed_jobs} falliti)`}
                          </span>
                        </div>
                        <Progress value={getProgress(batch)} />
                      </div>

                      <div className="flex gap-2 flex-wrap">
                        <Button 
                          onClick={() => navigate(`/batch/${batch.id}`)}
                          size="sm"
                          variant="default"
                        >
                          <Eye className="mr-2 h-4 w-4" />
                          Vedi Dettagli
                        </Button>

                        {batch.status === 'pending' || batch.status === 'paused' ? (
                          <Button onClick={() => startBatch(batch.id)} size="sm">
                            <Play className="mr-2 h-4 w-4" />
                            Avvia
                          </Button>
                        ) : null}
                        
                        {batch.status === 'running' && (
                          <Button onClick={() => pauseBatch(batch.id)} size="sm" variant="outline">
                            <Pause className="mr-2 h-4 w-4" />
                            Pausa
                          </Button>
                        )}

                        <Button 
                          onClick={() => exportBatchJobs(batch.id, batch.name)}
                          size="sm" 
                          variant="outline"
                        >
                          <FileDown className="mr-2 h-4 w-4" />
                          Esporta CSV
                        </Button>

                        <Button 
                          onClick={() => deleteBatch(batch.id)} 
                          size="sm" 
                          variant="destructive"
                        >
                          <Trash2 className="mr-2 h-4 w-4" />
                          Elimina
                        </Button>

                        <div className="ml-auto text-sm text-muted-foreground">
                          Delay: {batch.delay_seconds}s tra ricerche
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Download, ArrowLeft } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useNavigate } from "react-router-dom";
import * as XLSX from 'xlsx';

interface Contact {
  id: string;
  name: string | null;
  organization: string | null;
  email: string | null;
  phone: string | null;
  website: string | null;
  created_at: string;
  search_id: string;
}

const Contacts = () => {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const { toast } = useToast();
  const navigate = useNavigate();

  useEffect(() => {
    loadContacts();
  }, []);

  const loadContacts = async () => {
    setIsLoading(true);
    try {
      // Fetch all contacts with pagination to bypass the 1000 row limit
      let allContacts: Contact[] = [];
      let from = 0;
      const pageSize = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error } = await supabase
          .from('contacts')
          .select('*')
          .order('created_at', { ascending: false })
          .range(from, from + pageSize - 1);

        if (error) throw error;
        
        if (data && data.length > 0) {
          allContacts = [...allContacts, ...data];
          from += pageSize;
          hasMore = data.length === pageSize;
        } else {
          hasMore = false;
        }
      }

      setContacts(allContacts);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage || "Errore nel caricamento dei contatti",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const exportToExcel = () => {
    const dataToExport = contacts.map(c => ({
      Email: c.email || '',
      Nome: c.name || '',
      Organizzazione: c.organization || '',
      Telefono: c.phone || '',
      Website: c.website || '',
      'Data creazione': new Date(c.created_at).toLocaleString('it-IT'),
    }));
    
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Sheet1");
    XLSX.writeFile(workbook, 'tutti_i_contatti.xlsx');
    
    toast({
      title: "Export completato",
      description: "File scaricato con successo",
    });
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        <Button
          variant="outline"
          onClick={() => navigate('/dashboard')}
          className="mb-4"
        >
          <ArrowLeft className="mr-2 h-4 w-4" />
          Torna alla Dashboard
        </Button>
        
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle>Tutti i Contatti ({contacts.length})</CardTitle>
                <CardDescription>
                  Elenco completo dei contatti estratti dalle ricerche
                </CardDescription>
              </div>
              <Button onClick={exportToExcel} disabled={contacts.length === 0}>
                <Download className="mr-2 h-4 w-4" />
                Esporta in Excel
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <p className="text-center text-muted-foreground py-8">Caricamento...</p>
            ) : contacts.length === 0 ? (
              <p className="text-center text-muted-foreground py-8">Nessun contatto salvato</p>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Email</TableHead>
                      <TableHead>Nome</TableHead>
                      <TableHead>Organizzazione</TableHead>
                      <TableHead>Telefono</TableHead>
                      <TableHead>Website</TableHead>
                      <TableHead>Data</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {contacts.map((contact) => (
                      <TableRow key={contact.id}>
                        <TableCell className="font-medium">
                          {contact.email ? (
                            <a href={`mailto:${contact.email}`} className="text-primary hover:underline">
                              {contact.email}
                            </a>
                          ) : (
                            <span className="text-muted-foreground">N/A</span>
                          )}
                        </TableCell>
                        <TableCell>{contact.name || <span className="text-muted-foreground">N/A</span>}</TableCell>
                        <TableCell>{contact.organization || <span className="text-muted-foreground">N/A</span>}</TableCell>
                        <TableCell>{contact.phone || <span className="text-muted-foreground">N/A</span>}</TableCell>
                        <TableCell>
                          {contact.website ? (
                            <a href={contact.website} target="_blank" rel="noopener noreferrer" className="text-primary hover:underline">
                              Link
                            </a>
                          ) : (
                            <span className="text-muted-foreground">N/A</span>
                          )}
                        </TableCell>
                        <TableCell className="text-sm text-muted-foreground">
                          {new Date(contact.created_at).toLocaleDateString('it-IT')}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default Contacts;

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Search, Mail, Zap, LogOut, CheckCircle, BookOpen, User } from "lucide-react";
import logo from "@/assets/logo.png";
import { useNavigate } from "react-router-dom";
import { useToast } from "@/hooks/use-toast";
import { UsageStats } from "@/components/UsageStats";


const Dashboard = () => {
  const [contactsCount, setContactsCount] = useState(0);
  const [searchesCount, setSearchesCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();
  const { toast } = useToast();

  const handleLogout = async () => {
    await supabase.auth.signOut();
    toast({
      title: "Disconnesso",
      description: "Sei stato disconnesso con successo",
    });
    navigate('/auth');
  };

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const [contactsRes, searchesRes] = await Promise.all([
        supabase.from('contacts').select('id', { count: 'exact', head: true }),
        supabase.from('searches').select('id', { count: 'exact', head: true })
      ]);

      setContactsCount(contactsRes.count || 0);
      setSearchesCount(searchesRes.count || 0);
    } catch (error: any) {
      console.error('Error loading data:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        {/* Header with Actions */}
        <header className="flex justify-between items-center mb-12">
          <div className="flex items-center gap-4">
            <img src={logo} alt="BluelimeLeads.com" className="h-14 w-auto" style={{ width: '44.8px' }} />
            <div>
              <h1 className="text-3xl font-bold bg-gradient-to-r from-green-500 to-blue-500 bg-clip-text text-transparent">BluelimeLeads.com</h1>
              <p className="text-muted-foreground mt-1">Dashboard centrale</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button onClick={() => navigate('/profile')} variant="ghost" size="sm">
              <User className="mr-2 h-4 w-4" />
              Profilo
            </Button>
            <Button onClick={handleLogout} variant="outline" size="sm">
              <LogOut className="mr-2 h-4 w-4" />
              Esci
            </Button>
          </div>
        </header>

        {isLoading ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        ) : (
          <>
            {/* Quick Actions */}
            <div className="mb-12">
              <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                <span className="text-secondary">→</span> Azioni Rapide
              </h2>
              <div className="grid gap-4 md:grid-cols-4">
                <Button 
                  onClick={() => navigate('/search')}
                  size="lg"
                  className="h-24 bg-primary hover:bg-primary/90 text-lg font-semibold"
                >
                  <Search className="mr-3 h-6 w-6" />
                  Nuova Ricerca
                </Button>
                <Button 
                  onClick={() => navigate('/batch')}
                  size="lg"
                  className="h-24 bg-secondary hover:bg-secondary/90 text-lg font-semibold"
                >
                  <Zap className="mr-3 h-6 w-6" />
                  Batch Manager
                </Button>
                <Button 
                  onClick={() => navigate('/guide')}
                  size="lg"
                  variant="outline"
                  className="h-24 text-lg font-semibold border-2"
                >
                  <BookOpen className="mr-3 h-6 w-6" />
                  Guida Utente
                </Button>
                <Button 
                  onClick={() => navigate('/validate')}
                  size="lg"
                  className="h-24 bg-gradient-to-r from-emerald-600 to-green-600 hover:from-emerald-700 hover:to-green-700 text-lg font-semibold relative overflow-hidden"
                >
                  <div className="absolute top-2 right-2">
                    <span className="text-xs bg-white/20 px-2 py-0.5 rounded-full">∞ Unlimited</span>
                  </div>
                  <CheckCircle className="mr-3 h-6 w-6" />
                  Validazione Email
                </Button>
              </div>
            </div>

            {/* Usage Stats */}
            <div className="mb-8">
              <h2 
                className="text-xl font-semibold mb-4 flex items-center gap-2 cursor-pointer hover:text-primary transition-colors"
                onClick={() => navigate('/pricing')}
              >
                <span className="text-primary">⚡</span> Il tuo Piano
              </h2>
              <UsageStats />
            </div>

            {/* Stats Cards */}
            <div className="mb-8">
              <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                <span className="text-accent">📊</span> Statistiche
              </h2>
              <div className="grid gap-6 md:grid-cols-2">
                <div 
                  onClick={() => navigate('/contacts')}
                  className="cursor-pointer transition-all hover:scale-105 hover:shadow-lg hover:shadow-primary/20"
                >
                  <Card className="border-2 border-border hover:border-primary">
                    <CardHeader>
                      <CardTitle className="flex items-center gap-2 text-primary">
                        <Mail className="h-5 w-5" />
                        Contatti Salvati
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="text-5xl font-bold text-primary">{contactsCount}</div>
                      <p className="text-sm text-muted-foreground mt-2">Clicca per visualizzare tutti</p>
                    </CardContent>
                  </Card>
                </div>

                <div 
                  onClick={() => navigate('/searches')}
                  className="cursor-pointer transition-all hover:scale-105 hover:shadow-lg hover:shadow-secondary/20"
                >
                  <Card className="border-2 border-border hover:border-secondary">
                    <CardHeader>
                      <CardTitle className="flex items-center gap-2 text-secondary">
                        <Search className="h-5 w-5" />
                        Ricerche Effettuate
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="text-5xl font-bold text-secondary">{searchesCount}</div>
                      <p className="text-sm text-muted-foreground mt-2">Clicca per lo storico</p>
                    </CardContent>
                  </Card>
                </div>
              </div>
            </div>

          </>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { Loader2, User, MapPin, Phone, Building, ArrowLeft, Camera } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { ProfileCharts } from "@/components/ProfileCharts";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

interface ProfileData {
  id: string;
  email: string;
  full_name: string | null;
  phone: string | null;
  address: string | null;
  city: string | null;
  country: string | null;
  company: string | null;
  plan_id: string;
  last_name?: string | null; // Aggiunto campo cognome
}

const Profile = () => {
  const navigate = useNavigate();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [profile, setProfile] = useState<ProfileData | null>(null);

  useEffect(() => {
    loadProfile();
  }, []);

  const loadProfile = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        navigate("/auth");
        return;
      }

      const { data, error } = await supabase
        .from("profiles")
        .select("*")
        .eq("id", user.id)
        .single();

      if (error) throw error;
      
      // Get avatar_url from user metadata
      const avatarUrl = user.user_metadata?.avatar_url;
      setProfile({ ...data, avatar_url: avatarUrl });
    } catch (error) {
      console.error("Error loading profile:", error);
      toast({
        title: "Errore",
        description: "Impossibile caricare il profilo",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!profile) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from("profiles")
        .update({
          full_name: profile.full_name,
          last_name: profile.last_name,
          phone: profile.phone,
          address: profile.address,
          city: profile.city,
          country: profile.country,
          company: profile.company,
          updated_at: new Date().toISOString(),
        })
        .eq("id", profile.id);

      if (error) throw error;

      toast({
        title: "Profilo aggiornato",
        description: "I tuoi dati sono stati salvati con successo",
      });
    } catch (error) {
      console.error("Error updating profile:", error);
      toast({
        title: "Errore",
        description: "Impossibile aggiornare il profilo",
        variant: "destructive",
      });
    } finally {
      setSaving(false);
    }
  };

  const handleAvatarUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${profile.id}.${fileExt}`;
      const filePath = `${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('avatar')
        .upload(filePath, file, { upsert: true });

      if (uploadError) throw uploadError;

      const { data } = supabase.storage
        .from('avatar')
        .getPublicUrl(filePath);

      // Update user metadata with new avatar URL
      const { error: updateError } = await supabase.auth.updateUser({
        data: { avatar_url: data.publicUrl }
      });

      if (updateError) throw updateError;

      setProfile({ ...profile, avatar_url: data.publicUrl });

      toast({
        title: 'Successo',
        description: 'Foto profilo aggiornata!',
      });
    } catch (error: any) {
      console.error('Upload error:', error);
      toast({
        variant: 'destructive',
        title: 'Errore',
        description: error.message || 'Impossibile caricare la foto profilo',
      });
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  if (!profile) return null;

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-8">
          <Button
            variant="ghost"
            onClick={() => navigate('/dashboard')}
            className="mb-4"
          >
            <ArrowLeft className="mr-2 h-4 w-4" />
            Torna alla Dashboard
          </Button>
          <h1 className="text-3xl font-bold">Il tuo Profilo</h1>
          <p className="text-muted-foreground">Gestisci le tue informazioni personali e monitora le tue attività.</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Column - User Card + Activity Chart */}
          <div className="space-y-6">
            {/* User Profile Card with Gradient */}
            <Card className="relative overflow-hidden">
              <div className="h-24 bg-gradient-to-r from-orange-400 via-pink-400 to-purple-500" />
              <CardContent className="relative pt-0 pb-6">
                <div className="flex flex-col items-center -mt-16">
                  <div className="relative">
                    <Avatar className="h-32 w-32 border-8 border-card shadow-xl ring-4 ring-primary/20 bg-card">
                      <AvatarImage src={profile.avatar_url} className="object-cover" />
                      <AvatarFallback className="text-4xl bg-blue-500 text-white">
                        {profile.full_name?.charAt(0).toUpperCase() || profile.email.charAt(0).toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                    <label
                      htmlFor="avatar-upload"
                      className="absolute bottom-0 right-0 p-2 bg-primary text-primary-foreground rounded-full border-4 border-card cursor-pointer hover:bg-primary/90 shadow-lg"
                    >
                      <Camera className="h-5 w-5" />
                    </label>
                    <input
                      id="avatar-upload"
                      type="file"
                      accept="image/*"
                      onChange={handleAvatarUpload}
                      className="hidden"
                    />
                  </div>
                  <h2 className="mt-6 text-xl font-bold">{profile.full_name || 'Utente'}</h2>
                  <p className="text-sm text-muted-foreground">{profile.email}</p>
                  <Button
                    variant="outline"
                    size="sm"
                    className="mt-4"
                    onClick={() => document.getElementById('avatar-upload')?.click()}
                  >
                    <Camera className="mr-2 h-4 w-4" />
                    Cambia Foto
                  </Button>
                </div>
              </CardContent>
            </Card>

            {/* Activity Chart */}
            <Card>
              <CardHeader>
                <CardTitle>Attività Recente</CardTitle>
              </CardHeader>
              <CardContent>
                <ProfileCharts />
              </CardContent>
            </Card>
          </div>

          {/* Right Column - Personal Information Form */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <div className="flex items-center gap-2">
                  <User className="h-5 w-5 text-primary" />
                  <CardTitle>Informazioni Personali</CardTitle>
                </div>
                <CardDescription>
                  Completa il tuo profilo per aiutarci a offrirti un servizio migliore.
                </CardDescription>
              </CardHeader>
              <CardContent>
                <form onSubmit={(e) => { e.preventDefault(); handleSave(); }} className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="email">Email</Label>
                      <div className="relative">
                        <User className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                        <Input 
                          id="email" 
                          value={profile.email} 
                          disabled 
                          className="pl-9"
                        />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="fullName">Nome Completo</Label>
                      <div className="relative">
                        <User className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                        <Input 
                          id="fullName" 
                          placeholder="Mario Rossi" 
                          value={profile.full_name || ''}
                          onChange={(e) => setProfile({...profile, full_name: e.target.value})}
                          className="pl-9"
                        />
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="phone">Telefono</Label>
                      <div className="relative">
                        <Phone className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                        <Input 
                          id="phone" 
                          placeholder="+39 333 1234567" 
                          value={profile.phone || ''}
                          onChange={(e) => setProfile({...profile, phone: e.target.value})}
                          className="pl-9"
                        />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="company">Azienda</Label>
                      <div className="relative">
                        <Building className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                        <Input 
                          id="company" 
                          placeholder="La Tua Azienda Srl" 
                          value={profile.company || ''}
                          onChange={(e) => setProfile({...profile, company: e.target.value})}
                          className="pl-9"
                        />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="address">Indirizzo</Label>
                    <div className="relative">
                      <MapPin className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                      <Input 
                        id="address" 
                        placeholder="Via Roma 1" 
                        value={profile.address || ''}
                        onChange={(e) => setProfile({...profile, address: e.target.value})}
                        className="pl-9"
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="city">Città</Label>
                      <Input 
                        id="city" 
                        placeholder="Milano" 
                        value={profile.city || ''}
                        onChange={(e) => setProfile({...profile, city: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="country">Paese</Label>
                      <Input 
                        id="country" 
                        placeholder="Italia" 
                        value={profile.country || ''}
                        onChange={(e) => setProfile({...profile, country: e.target.value})}
                      />
                    </div>
                  </div>

                  <div className="pt-4">
                    <Button type="submit" disabled={saving} size="lg" className="w-full md:w-auto">
                      {saving ? (
                        <>
                          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                          Salvataggio...
                        </>
                      ) : (
                        'Salva Modifiche'
                      )}
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profile;

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { ArrowLeft } from "lucide-react";
import logo from "@/assets/logo.png";
import { useNavigate } from "react-router-dom";
import { useToast } from "@/hooks/use-toast";
import { AdvancedQueryBuilder } from "@/components/AdvancedQueryBuilder";
import { ContactsTable } from "@/components/ContactsTable";

const Search = () => {
  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const navigate = useNavigate();
  const { toast } = useToast();

  const handleSearch = async (searchParams: any) => {
    setIsSearching(true);
    setSearchResults([]);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Utente non autenticato");

      const { data, error } = await supabase.functions.invoke('search-contacts', {
        body: searchParams
      });

      if (error) throw error;

      if (data?.contacts) {
        setSearchResults(data.contacts);
        toast({
          title: "Ricerca completata",
          description: `Trovati ${data.contacts.length} contatti`,
        });
      }
    } catch (error: any) {
      toast({
        title: "Errore",
        description: error.message || "Errore durante la ricerca",
        variant: "destructive",
      });
    } finally {
      setIsSearching(false);
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <header className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            <img src={logo} alt="BluelimeLeads.com" className="h-14 w-auto" style={{ width: '44.8px' }} />
            <div>
              <h1 className="text-3xl font-bold bg-gradient-to-r from-green-500 to-blue-500 bg-clip-text text-transparent">BluelimeLeads.com</h1>
              <p className="text-muted-foreground mt-1">Nuova Ricerca</p>
            </div>
          </div>
          <Button onClick={() => navigate('/dashboard')} variant="outline">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Torna alla Dashboard
          </Button>
        </header>

        {/* Search Form - Full Width */}
        <div className="mb-8">
          <AdvancedQueryBuilder 
            onQueryGenerated={(query) => console.log('Query generata:', query)}
            onSearch={handleSearch}
          />
        </div>

        {/* Search Results */}
        {(searchResults.length > 0 || isSearching) && (
          <div className="mt-8">
            <ContactsTable 
              contacts={searchResults} 
              isLoading={isSearching}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default Search;

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Download, ArrowLeft } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useNavigate } from "react-router-dom";
import * as XLSX from 'xlsx';

interface Contact {
  id: string;
  search_id: string;
}

interface SearchRecord {
  id: string;
  query: string;
  location: string | null;
  created_at: string;
}

const Searches = () => {
  const [searches, setSearches] = useState<SearchRecord[]>([]);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const { toast } = useToast();
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      
      if (!user) {
        throw new Error("Utente non autenticato");
      }

      // First get all user's searches
      const searchesRes = await supabase
        .from('searches')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (searchesRes.error) throw searchesRes.error;

      const searchIds = (searchesRes.data || []).map(s => s.id);

      // Then get contacts for those searches
      const contactsRes = searchIds.length > 0 
        ? await supabase.from('contacts').select('id, search_id').in('search_id', searchIds)
        : { data: [], error: null };

      if (contactsRes.error) throw contactsRes.error;

      setSearches(searchesRes.data || []);
      setContacts(contactsRes.data || []);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage || "Errore nel caricamento dei dati",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const exportSearchContacts = async (searchId: string, searchQuery: string) => {
    try {
      const { data, error } = await supabase
        .from('contacts')
        .select('*')
        .eq('search_id', searchId);

      if (error) throw error;

      const dataToExport = (data || []).map(c => ({
        Email: c.email || '',
        Nome: c.name || '',
        Organizzazione: c.organization || '',
        Telefono: c.phone || '',
        Website: c.website || '',
        'Data creazione': new Date(c.created_at).toLocaleString('it-IT'),
      }));

      const worksheet = XLSX.utils.json_to_sheet(dataToExport);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Sheet1");
      const filename = `contatti_${searchQuery.replace(/\s+/g, '_').toLowerCase()}.xlsx`;
      XLSX.writeFile(workbook, filename);

      toast({
        title: "Export completato",
        description: `File ${filename} scaricato con successo`,
      });
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage || "Errore nell'export",
        variant: "destructive",
      });
    }
  };

  const exportAllSearches = () => {
    const dataToExport = searches.map(s => ({
      Query: s.query,
      Località: s.location || '',
      'Data ricerca': new Date(s.created_at).toLocaleString('it-IT'),
    }));

    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Sheet1");
    XLSX.writeFile(workbook, 'ricerche.xlsx');

    toast({
      title: "Export completato",
      description: "File ricerche.xlsx scaricato con successo",
    });
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        <Button
          variant="outline"
          onClick={() => navigate('/dashboard')}
          className="mb-4"
        >
          <ArrowLeft className="mr-2 h-4 w-4" />
          Torna alla Dashboard
        </Button>

        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle>Ricerche effettuate ({searches.length})</CardTitle>
                <CardDescription>
                  Storico di tutte le ricerche
                </CardDescription>
              </div>
              <Button onClick={exportAllSearches} disabled={searches.length === 0}>
                <Download className="mr-2 h-4 w-4" />
                Esporta in Excel
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <p className="text-center text-muted-foreground py-8">Caricamento...</p>
            ) : searches.length === 0 ? (
              <p className="text-center text-muted-foreground py-8">Nessuna ricerca salvata</p>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Query</TableHead>
                      <TableHead>Località</TableHead>
                      <TableHead>Contatti trovati</TableHead>
                      <TableHead>Data ricerca</TableHead>
                      <TableHead>Azioni</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {searches.map((search) => {
                      const searchContactsCount = contacts.filter(c => c.search_id === search.id).length;
                      return (
                        <TableRow key={search.id}>
                          <TableCell className="font-medium">{search.query}</TableCell>
                          <TableCell>{search.location || <span className="text-muted-foreground">Nessuna</span>}</TableCell>
                          <TableCell>
                            <span className="inline-flex items-center rounded-full bg-primary/10 px-2.5 py-0.5 text-xs font-medium text-primary">
                              {searchContactsCount} contatti
                            </span>
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            {new Date(search.created_at).toLocaleString('it-IT')}
                          </TableCell>
                          <TableCell>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => exportSearchContacts(search.id, search.query)}
                              disabled={searchContactsCount === 0}
                            >
                              <Download className="mr-2 h-4 w-4" />
                              Esporta
                            </Button>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default Searches;

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Upload, ArrowLeft, Search, FileText, Trash2, Play, Loader2 } from "lucide-react";
import { Link, useNavigate } from "react-router-dom";
import * as XLSX from "xlsx";
import { Badge } from "@/components/ui/badge";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";

interface ValidationList {
  id: string;
  name: string;
  total_emails: number;
  processed_emails: number;
  deliverable_count: number;
  undeliverable_count: number;
  risky_count: number;
  unknown_count: number;
  status: string;
  created_at: string;
}

interface ValidationResult {
  id: string;
  email: string;
  result: string;
  format_valid: boolean;
  domain_valid: boolean;
  smtp_valid: boolean;
  catch_all: boolean;
  disposable: boolean;
  free_email: boolean;
  reason: string | null;
  deliverable: boolean;
  full_response: any;
}

const Validate = () => {
  const navigate = useNavigate();
  const [emails, setEmails] = useState<string[]>([]);
  const [pastedEmails, setPastedEmails] = useState("");
  const [listName, setListName] = useState("");
  const [isCreating, setIsCreating] = useState(false);
  const [validationHistory, setValidationHistory] = useState<ValidationList[]>([]);
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => {
    loadValidationHistory();
  }, []);

  const loadValidationHistory = async () => {
    const { data, error } = await supabase
      .from("validation_lists")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Error loading history:", error);
      return;
    }

    setValidationHistory(data || []);
  };

  const deleteList = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent navigation when clicking delete
    
    try {
      // Delete results first
      await supabase.from("validation_results").delete().eq("validation_list_id", id);
      // Delete contacts
      await supabase.from("contacts").delete().eq("list_id", id);
      // Delete list
      const { error } = await supabase.from("validation_lists").delete().eq("id", id);

      if (error) throw error;

      toast({
        title: "Lista eliminata",
        description: "La lista è stata rimossa correttamente",
      });
      loadValidationHistory();
    } catch (error) {
      console.error("Error deleting list:", error);
      toast({
        title: "Errore",
        description: "Impossibile eliminare la lista",
        variant: "destructive",
      });
    }
  };

  const handlePasteEmails = () => {
    const lines = pastedEmails.split('\n').map(line => line.trim()).filter(line => line.length > 0);
    const emailList: string[] = [];
    
    lines.forEach(line => {
      // Extract emails from each line (in case there's text around them)
      const emailRegex = /[\w.-]+@[\w.-]+\.\w+/g;
      const matches = line.match(emailRegex);
      if (matches) {
        emailList.push(...matches);
      }
    });

    const uniqueEmails = [...new Set(emailList)];
    setEmails(uniqueEmails);
    toast({
      title: "Email incollate",
      description: `${uniqueEmails.length} email uniche trovate`,
    });
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: "array" });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(firstSheet, { header: 1 });

        const emailList: string[] = [];
        jsonData.forEach((row: any) => {
          if (Array.isArray(row)) {
            row.forEach((cell) => {
              if (typeof cell === "string" && cell.includes("@")) {
                emailList.push(cell.trim());
              }
            });
          }
        });

        setEmails([...new Set(emailList)]);
        
        // Auto-set list name from file name if empty
        if (!listName && file.name) {
          const nameWithoutExt = file.name.split('.').slice(0, -1).join('.');
          setListName(nameWithoutExt);
        }

        toast({
          title: "File caricato",
          description: `${emailList.length} email uniche trovate`,
        });
      } catch (error) {
        toast({
          title: "Errore",
          description: "Impossibile leggere il file",
          variant: "destructive",
        });
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleValidateNow = async () => {
    if (emails.length === 0) {
      toast({
        title: "Nessuna email",
        description: "Carica prima un file con le email",
        variant: "destructive",
      });
      return;
    }

    if (!listName) {
      toast({
        title: "Nome richiesto",
        description: "Inserisci un nome per questa lista",
        variant: "destructive",
      });
      return;
    }

    setIsCreating(true);

    try {
      // 1. Get current user
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("User not authenticated");

      // 2. Create List with status 'processing' immediately
      const { data: list, error: listError } = await supabase
        .from("validation_lists")
        .insert({
          name: listName,
          user_id: user.id,
          total_emails: emails.length,
          status: 'processing',
          processed_emails: 0
        })
        .select()
        .single();

      if (listError) throw listError;

      // 3. Insert Contacts (in batches of 1000 to be safe)
      const contactsData = emails.map(email => ({
        list_id: list.id,
        email: email,
        name: email.split('@')[0] // Simple name extraction
      }));

      const batchSize = 1000;
      for (let i = 0; i < contactsData.length; i += batchSize) {
        const batch = contactsData.slice(i, i + batchSize);
        const { error: contactsError } = await supabase
          .from("contacts")
          .insert(batch);
        
        if (contactsError) throw contactsError;
      }

      // 4. Trigger Validation Immediately
      const { error: validationError } = await supabase.functions.invoke("validate-batch", {
        body: { 
          emails, 
          listName: list.name,
          existingListId: list.id 
        },
      });

      if (validationError) throw validationError;

      toast({
        title: "🚀 Validazione avviata",
        description: "Analisi della lista in corso...",
      });

      // 5. Navigate immediately to results
      navigate(`/validate/${list.id}`);
      
    } catch (error: any) {
      console.error("Error creating list:", error);
      toast({
        title: "Errore",
        description: error.message || "Impossibile avviare la validazione",
        variant: "destructive",
      });
      setIsCreating(false); // Only reset if error, otherwise we navigate away
    }
  };

  const filteredLists = validationHistory.filter((list) =>
    list.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const getStatusBadge = (status: string) => {
    if (status === "completed") {
      return <Badge className="bg-emerald-500/20 text-emerald-400 border-emerald-500/30">Completata</Badge>;
    }
    if (status === "unvalidated") {
      return <Badge className="bg-amber-500/20 text-amber-400 border-amber-500/30">Da validare</Badge>;
    }
    if (status === "processing") {
      return <Badge className="bg-blue-500/20 text-blue-400 border-blue-500/30">In corso...</Badge>;
    }
    if (status === "pending") {
      return <Badge className="bg-slate-500/20 text-slate-400 border-slate-500/30">In attesa</Badge>;
    }
    if (status === "failed") {
      return <Badge className="bg-red-500/20 text-red-400 border-red-500/30">Fallita</Badge>;
    }
    return <Badge variant="secondary">{status}</Badge>;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950">
      <div className="container mx-auto p-6 max-w-7xl">
        {/* Header */}
        <div className="mb-8">
          <Link to="/dashboard">
            <Button variant="ghost" size="sm" className="mb-4 text-slate-400 hover:text-slate-200">
              <ArrowLeft className="mr-2 h-4 w-4" />
              Dashboard
            </Button>
          </Link>
          <h1 className="text-4xl font-bold mb-2 text-white">Validazione Lista</h1>
          <p className="text-slate-400">
            Valida più indirizzi email contemporaneamente ed esporta i risultati • Validazioni illimitate
          </p>
        </div>

        {/* Pick a Source */}
        <Card className="p-6 mb-6 bg-slate-900/50 border-slate-800">
          <h2 className="text-lg font-semibold mb-4 text-white">Scegli una Sorgente</h2>
          
          <div className="space-y-4">
            <Input
              placeholder="Nome lista (es: Lista clienti Q4 2024)"
              value={listName}
              onChange={(e) => setListName(e.target.value)}
              disabled={isCreating}
              className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-500"
            />

            <Tabs defaultValue="paste" className="w-full">
              <TabsList className="grid w-full grid-cols-2 bg-slate-800/50">
                <TabsTrigger value="paste" className="data-[state=active]:bg-slate-700">
                  <FileText className="mr-2 h-4 w-4" />
                  Incolla una lista
                </TabsTrigger>
                <TabsTrigger value="upload" className="data-[state=active]:bg-slate-700">
                  <Upload className="mr-2 h-4 w-4" />
                  Carica un file
                </TabsTrigger>
              </TabsList>
              
              <TabsContent value="paste" className="space-y-3">
                <Textarea
                  placeholder="Incolla le email qui (una per riga o separate da virgole)&#10;esempio@email.com&#10;altro@email.com"
                  value={pastedEmails}
                  onChange={(e) => setPastedEmails(e.target.value)}
                  disabled={isCreating}
                  className="min-h-[200px] bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-500 font-mono text-sm"
                />
                <Button
                  onClick={handlePasteEmails}
                  disabled={isCreating || !pastedEmails.trim()}
                  variant="outline"
                  className="w-full bg-slate-800/30 border-slate-700 hover:bg-slate-800 text-slate-300"
                >
                  Estrai Email
                </Button>
              </TabsContent>
              
              <TabsContent value="upload" className="space-y-3">
                <div className="border-2 border-dashed border-slate-700 rounded-lg p-8 text-center hover:border-slate-600 transition-colors">
                  <Upload className="h-12 w-12 mx-auto mb-4 text-slate-500" />
                  <p className="text-sm text-slate-400 mb-2">
                    Carica un file CSV o Excel
                  </p>
                  <Button
                    variant="outline"
                    className="bg-slate-800/30 border-slate-700 hover:bg-slate-800 text-slate-300 relative"
                    asChild
                  >
                    <label>
                      Seleziona file
                      <Input
                        type="file"
                        accept=".csv,.xlsx,.xls"
                        onChange={handleFileUpload}
                        disabled={isCreating}
                        className="absolute inset-0 opacity-0 cursor-pointer"
                      />
                    </label>
                  </Button>
                </div>
              </TabsContent>
            </Tabs>

            {emails.length > 0 && (
              <div className="bg-slate-800/30 p-4 rounded-lg border border-slate-700">
                <div className="flex items-center justify-between mb-2">
                  <span className="font-medium text-white">Email da validare:</span>
                  <Badge className="bg-blue-500/20 text-blue-400 border-blue-500/30">
                    {emails.length} email
                  </Badge>
                </div>
                <div className="max-h-32 overflow-y-auto space-y-1 text-sm mb-3">
                  {emails.slice(0, 10).map((email, idx) => (
                    <div key={idx} className="text-slate-400 font-mono text-xs">
                      {email}
                    </div>
                  ))}
                  {emails.length > 10 && (
                    <div className="text-slate-500 italic text-xs">
                      ... e altre {emails.length - 10} email
                    </div>
                  )}
                </div>
                
                <Button
                  onClick={handleValidateNow}
                  disabled={isCreating}
                  className="w-full bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 shadow-lg shadow-emerald-500/20"
                  size="lg"
                >
                  {isCreating ? (
                    <>
                      <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                      Avvio validazione...
                    </>
                  ) : (
                    <>
                      <Play className="mr-2 h-5 w-5" />
                      Valida Ora
                    </>
                  )}
                </Button>
              </div>
            )}
          </div>
        </Card>

        {/* My Lists */}
        <Card className="p-6 bg-slate-900/50 border-slate-800">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-semibold text-white">
              Le Mie Liste ({filteredLists.length})
            </h2>
            <div className="relative w-64">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-slate-500" />
              <Input
                placeholder="Cerca liste..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-500"
              />
            </div>
          </div>

          {filteredLists.length > 0 ? (
            <div className="space-y-3">
              {filteredLists.map((list) => (
                <div
                  key={list.id}
                  onClick={() => navigate(`/validate/${list.id}`)}
                  className="flex items-center justify-between p-4 rounded-lg bg-slate-800/30 border border-slate-700 hover:border-slate-600 transition-colors cursor-pointer group"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-1">
                      <h3 className="font-semibold text-white group-hover:text-blue-400 transition-colors">{list.name}</h3>
                      {getStatusBadge(list.status)}
                    </div>
                    <div className="flex items-center gap-4 text-sm text-slate-400">
                      <span>
                        Creata {new Date(list.created_at).toLocaleDateString("it-IT", {
                          day: "2-digit",
                          month: "2-digit",
                          year: "numeric",
                          hour: "2-digit",
                          minute: "2-digit"
                        })}
                      </span>
                      <span className="text-slate-500">•</span>
                      <span>{list.total_emails} email</span>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    <Button
                      size="sm"
                      variant="ghost"
                      className={
                        list.status === "unvalidated"
                          ? "text-amber-400 hover:text-amber-300 hover:bg-amber-900/20"
                          : "text-cyan-400 hover:text-cyan-300 hover:bg-cyan-900/20"
                      }
                    >
                      <Search className="mr-2 h-4 w-4" />
                      {list.status === "unvalidated" ? "Valida" : "Vedi risultati"}
                    </Button>

                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button 
                          variant="ghost" 
                          size="icon" 
                          className="text-slate-500 hover:text-red-400 hover:bg-red-900/20"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent className="bg-slate-900 border-slate-800 text-white" onClick={(e) => e.stopPropagation()}>
                        <AlertDialogHeader>
                          <AlertDialogTitle>Elimina Lista</AlertDialogTitle>
                          <AlertDialogDescription className="text-slate-400">
                            Sei sicuro di voler eliminare la lista "{list.name}"? Questa azione non può essere annullata.
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel className="bg-slate-800 text-white border-slate-700 hover:bg-slate-700">Annulla</AlertDialogCancel>
                          <AlertDialogAction onClick={(e) => deleteList(list.id, e)} className="bg-red-600 hover:bg-red-700 text-white">Elimina</AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-12 text-slate-500">
              <FileText className="h-16 w-16 mx-auto mb-4 opacity-20" />
              <p>Nessuna lista trovata</p>
            </div>
          )}
        </Card>
      </div>
    </div>
  );
};

export default Validate;

import { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { ArrowLeft, Download, Play, Loader2, Trash2 } from "lucide-react";
import { toast } from "@/hooks/use-toast";
import * as XLSX from "xlsx";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { ValidationCharts } from "@/components/ValidationCharts";
import { ValidationTable } from "@/components/ValidationTable";
import { ValidationList, ValidationResult } from "@/types/validation";

const ValidationResults = () => {
  const { listId } = useParams();
  const navigate = useNavigate();
  const [list, setList] = useState<ValidationList | null>(null);
  const [results, setResults] = useState<ValidationResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [isStartingValidation, setIsStartingValidation] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    if (listId) {
      loadData(true);
    }
  }, [listId]);

  // Auto-refresh while processing (no extra worker calls)
  useEffect(() => {
    if (!list || list.status !== 'processing') return;
    
    const interval = setInterval(async () => {
      // 1. Force check with Truelist (in case webhook failed)
      // This will check all "processing" lists and update them if Truelist is done
      await supabase.functions.invoke('process-validation-batch');

      // 2. Reload data from DB to see the update
      loadData();
    }, 5000);

    return () => clearInterval(interval);
  }, [list?.status]);

  const loadData = async (initial = false) => {
    if (initial) setLoading(true);
    
    // Load list info
    const { data: listData } = await supabase
      .from("validation_lists")
      .select("*")
      .eq("id", listId)
      .single();

    if (listData) {
      setList(listData);
    }

    // Load results
    const { data: resultsData } = await supabase
      .from("validation_results")
      .select("*")
      .eq("validation_list_id", listId);

    if (resultsData && resultsData.length > 0) {
      setResults(resultsData);
    } else {
      // If no results, load contacts to show them as pending
      const { data: contactsData } = await supabase
        .from("contacts")
        .select("*")
        .eq("list_id", listId);
        
      if (contactsData) {
        // Map contacts to ValidationResult interface
        const pendingResults: ValidationResult[] = contactsData.map(c => ({
          id: c.id, // Use contact ID temporarily
          email: c.email || "",
          result: "pending",
          format_valid: true,
          domain_valid: true,
          smtp_valid: false,
          catch_all: false,
          disposable: false,
          free_email: false,
          reason: null,
          deliverable: false,
          full_response: null
        }));
        setResults(pendingResults);
      }
    }

    if (initial) setLoading(false);
  };

  const deleteList = async () => {
    if (!listId) return;
    setIsDeleting(true);
    try {
      // Delete results first (if cascade not set up, but usually it is)
      const { error: resultsError } = await supabase
        .from("validation_results")
        .delete()
        .eq("validation_list_id", listId);

      if (resultsError) throw resultsError;

      // Delete list
      const { error: listError } = await supabase
        .from("validation_lists")
        .delete()
        .eq("id", listId);

      if (listError) throw listError;

      toast({
        title: "Lista eliminata",
        description: "La lista e tutti i risultati sono stati eliminati",
      });
      navigate("/validate");
    } catch (error) {
      console.error("Error deleting list:", error);
      toast({
        title: "Errore",
        description: "Impossibile eliminare la lista",
        variant: "destructive",
      });
    } finally {
      setIsDeleting(false);
    }
  };

  const deleteEmail = async (resultId: string) => {
    try {
      // Try to delete from validation_results first
      const { error: resultError } = await supabase
        .from("validation_results")
        .delete()
        .eq("id", resultId);

      // If it fails or if we are in "pending" mode (using contact IDs), try deleting from contacts
      if (resultError || results.find(r => r.id === resultId)?.result === 'pending') {
         const { error: contactError } = await supabase
          .from("contacts")
          .delete()
          .eq("id", resultId);
          
         if (contactError) throw contactError;
      }

      setResults(results.filter(r => r.id !== resultId));
      toast({
        title: "Email eliminata",
        description: "L'email è stata rimossa dalla lista",
      });
    } catch (error) {
      console.error("Error deleting email:", error);
      toast({
        title: "Errore",
        description: "Impossibile eliminare l'email",
        variant: "destructive",
      });
    }
  };

  const exportResults = (format: 'xlsx' | 'csv', onlyValid: boolean) => {
    const dataToExport = onlyValid
      ? results.filter((r) => r.deliverable)
      : results;

    const exportData = dataToExport.map((r) => ({
      Email: r.email,
      Result: r.result,
      Reason: r.reason || "",
      Format: r.format_valid ? "✓" : "✗",
      Domain: r.domain_valid ? "✓" : "✗",
      Deliverable: r.deliverable ? "✓" : "✗",
      "Catch-All": r.catch_all ? "Yes" : "No",
      Disposable: r.disposable ? "Yes" : "No",
      "Free Email": r.free_email ? "Yes" : "No",
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Results");

    const fileName = `${list?.name}_${onlyValid ? "valid" : "all"}_${Date.now()}.${format}`;
    
    if (format === 'csv') {
      XLSX.writeFile(workbook, fileName, { bookType: 'csv' });
    } else {
      XLSX.writeFile(workbook, fileName);
    }

    toast({
      title: "Export completato",
      description: `${dataToExport.length} email esportate in ${format.toUpperCase()}`,
    });
  };

  const startValidation = async () => {
    if (!list || !listId) return;
    
    setIsStartingValidation(true);
    
    try {
      // Get emails from contacts linked to this list
      const { data: contacts, error: contactsError } = await supabase
        .from("contacts")
        .select("email")
        .eq("list_id", listId)
        .not("email", "is", null);

      if (contactsError) throw contactsError;

      const emails = contacts
        ?.map(c => c.email)
        .filter((email): email is string => !!email) || [];

      if (emails.length === 0) {
        toast({
          title: "Nessuna email",
          description: "Non ci sono email da validare in questa lista",
          variant: "destructive",
        });
        setIsStartingValidation(false);
        return;
      }

      // Call validate-batch with existing list
      const { data, error } = await supabase.functions.invoke("validate-batch", {
        body: { 
          emails, 
          listName: list.name,
          existingListId: listId 
        },
      });

      if (error) throw error;

      toast({
        title: "✅ Validazione avviata",
        description: `${emails.length} email inviate a Truelist per la validazione`,
      });

      // Reload data to show processing status
      await loadData(true);

    } catch (error) {
      console.error("Error starting validation:", error);
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: "Errore",
        description: errorMessage || "Impossibile avviare la validazione",
        variant: "destructive",
      });
    } finally {
      setIsStartingValidation(false);
    }
  };

  if (loading || !list) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 flex items-center justify-center">
        <div className="text-white">Caricamento...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950">
      <div className="container mx-auto p-6 max-w-7xl">
        {/* Header */}
        <div className="mb-8 flex items-center justify-between">
          <div>
            <Link to="/validate">
              <Button
                variant="ghost"
                size="sm"
                className="mb-3 text-slate-400 hover:text-slate-200"
              >
                <ArrowLeft className="mr-2 h-4 w-4" />
                Torna alle liste
              </Button>
            </Link>
            <h1 className="text-4xl font-bold text-white mb-1">{list.name}</h1>
            <p className="text-sm text-slate-400">
              Creata il {new Date(list.created_at).toLocaleDateString("it-IT", {
                day: "2-digit",
                month: "2-digit",
                year: "numeric",
                hour: "2-digit",
                minute: "2-digit"
              })}
            </p>
          </div>
          
          <div className="flex gap-3">
            {list.status === "unvalidated" ? (
              <Button
                onClick={startValidation}
                disabled={isStartingValidation}
                className="bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 shadow-lg shadow-amber-500/30"
              >
                {isStartingValidation ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Avvio in corso...
                  </>
                ) : (
                  <>
                    <Play className="mr-2 h-4 w-4" />
                    Avvia Validazione
                  </>
                )}
              </Button>
            ) : (
              <>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button
                      variant="outline"
                      className="bg-slate-800/50 border-slate-600 hover:bg-slate-700 text-slate-200"
                    >
                      <Download className="mr-2 h-4 w-4" />
                      Export
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700 text-slate-200">
                    <DropdownMenuItem onClick={() => exportResults('xlsx', false)}>
                      Tutto (XLSX)
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => exportResults('csv', false)}>
                      Tutto (CSV)
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => exportResults('xlsx', true)} className="text-emerald-400">
                      Solo Valide (XLSX)
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => exportResults('csv', true)} className="text-emerald-400">
                      Solo Valide (CSV)
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            )}
            
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button variant="destructive" size="icon" className="bg-red-500/10 hover:bg-red-500/20 text-red-500 border border-red-500/20">
                  <Trash2 className="h-4 w-4" />
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent className="bg-slate-900 border-slate-800 text-white">
                <AlertDialogHeader>
                  <AlertDialogTitle>Sei sicuro?</AlertDialogTitle>
                  <AlertDialogDescription className="text-slate-400">
                    Questa azione non può essere annullata. Eliminerà permanentemente la lista "{list.name}" e tutti i risultati associati.
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel className="bg-slate-800 text-white border-slate-700 hover:bg-slate-700">Annulla</AlertDialogCancel>
                  <AlertDialogAction onClick={deleteList} className="bg-red-600 hover:bg-red-700 text-white">Elimina</AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </div>
        </div>

        <ValidationCharts list={list} results={results} />
        <ValidationTable results={results} deleteEmail={deleteEmail} />
      </div>
    </div>
  );
};

export default ValidationResults;

export interface ValidationList {
  id: string;
  name: string;
  status: string;
  total_emails: number;
  processed_emails: number;
  deliverable_count: number;
  undeliverable_count: number;
  risky_count: number;
  unknown_count: number;
  created_at: string;
}

export interface ValidationResult {
  id: string;
  email: string;
  result: string;
  format_valid: boolean;
  domain_valid: boolean;
  smtp_valid: boolean;
  catch_all: boolean;
  disposable: boolean;
  free_email: boolean;
  reason: string | null;
  deliverable: boolean;
  full_response?: any;
}
